# v0.9.4：06 章关卡插画改为 HTML 页（替代裁切位图 07.jpg；无二维码、无链接）
_S=[('AI 时代变化',['技术范式升级','AI 重塑工作方式','机会与挑战并存']),('能力模型',['AI-Native 能力框架','核心能力拆解','从工程师到超级个体']),
('工具生态',['精选 AI 工具栈','模型 / Agent / 平台','提效与协同']),('成长路线',['阶段化学习路径','项目驱动实践','快速成长闭环']),
('资产沉淀',['知识 / 文档 / 工作流','模板 / 提示词 / 代码','持续复用与迭代']),('XWorkmate 工作空间',['统一管理与协同','AI-Native 生产力系统','持续进化的超级个体'])]
_M=[('知识管理','结构化沉淀你的知识资产'),('任务与项目','规划 / 跟踪 / 协同，高效完成任务'),('AI Agent','专属 Agent 助手，自动化执行'),('模型中心','接入主流模型，统一调用管理'),('工作流引擎','可视化编排，自动化工作流'),('开放生态','插件扩展')]
_V=['统一入口','数据互通','智能协同','持续进化','安全可控']
_st=''.join(f'''<div style="flex:1;background:#fff;border:1.5px solid #c7d2fe;border-radius:10px;padding:10px 7px;{'box-shadow:0 0 0 2px #6366f1;' if i==3 else ''}"><div style="width:22px;height:22px;border-radius:50%;background:#4f46e5;color:#fff;font-weight:800;font-size:15.6px;line-height:22px;text-align:center">{i+1}</div><div style="font-weight:800;font-size:16.2px;margin:5px 0 4px;color:#1e1b4b">{E(t)}</div>{''.join(f'<div style="font-size:13.0px;color:#475569;line-height:1.5">· {E(b)}</div>' for b in bs)}</div>'''+('<div style="align-self:center;color:#6366f1;font-weight:800">→</div>' if i<5 else '') for i,(t,bs) in enumerate(_S))
_md=''.join(f'<div style="flex:1;background:#fff;border:1.5px solid #ddd6fe;border-radius:10px;padding:12px 6px;text-align:center"><div style="font-weight:800;font-size:16.2px;color:#312e81">{E(a)}</div><div style="font-size:13.0px;color:#64748b;margin-top:4px;line-height:1.45">{E(b)}</div></div>' for a,b in _M)
_vc=''.join(f'<span style="display:inline-block;background:#fff;border:1px solid #c4b5fd;border-radius:14px;padding:3px 12px;margin:0 4px;font-size:14.3px;font-weight:700;color:#4c1d95">{E(v)}</span>' for v in _V)
def _card(n,d1,d2): return f'<div style="flex:1;background:#fff;border:1.5px solid #c7d2fe;border-radius:12px;padding:16px 16px"><div style="font-weight:800;font-size:19.5px;color:#1e1b4b">{n}</div><div style="font-size:15.0px;color:#475569;margin-top:4px">{d1}</div><div style="font-size:15.0px;color:#475569">{d2}</div></div>'
_box='background:#f5f3ff;border:1px solid #e0e7ff;border-radius:14px;padding:16px 12px 18px;margin-top:16px'
add(f'''<div class="kicker">第 06 章 · 关卡插画</div><h1>成长闭环与 AI-Native 工作空间</h1>
<div style="{_box}"><div style="font-weight:800;font-size:20.8px;text-align:center;color:#1e1b4b;margin-bottom:8px">A · AI 时代技术人成长的完整闭环</div><div style="display:flex;gap:4px">{_st}</div><div style="text-align:center;font-size:13.7px;color:#6366f1;margin-top:6px">↺ 工作空间里沉淀的资产，回流到下一轮能力升级</div></div>
<div style="{_box}"><div style="font-weight:800;font-size:20.8px;text-align:center;color:#1e1b4b;margin-bottom:8px">B · XWorkmate AI-Native 生产力工作空间</div><div style="display:flex;gap:6px">{_md}</div><div style="text-align:center;font-size:15.0px;font-weight:700;color:#4338ca;margin:9px 0 6px">把知识、任务、模型、Agent、文档和工作流放在同一个生产力系统里</div><div style="text-align:center">{_vc}</div></div>
<div style="{_box}"><div style="font-weight:800;font-size:20.8px;text-align:center;color:#1e1b4b;margin-bottom:8px">C · 两件产品</div><div style="display:flex;gap:10px">{_card('XWorkmate App','AI-Native 移动端生产力工具','随时随地，AI 助你高效工作')}{_card('XWorkspace Console','AI-Native Workspace 工作空间','团队协同，构建你的 AI 工作台')}</div></div>''','06 关卡插画')
